// computeDiff gets the current uncommitted diff in the repo.
func computeDiff(repoRoot string) (string, error) {
	// Try uncommitted changes first

	cmd := exec.CommandContext(context.Background(), "git", "diff", "HEAD")
	cmd.Dir = repoRoot
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		// If HEAD doesn't exist (initial commit), try diff of staged/unstaged

		cmd2 := exec.CommandContext(context.Background(), "git", "diff")
		cmd2.Dir = repoRoot
		var stdout2 bytes.Buffer
		cmd2.Stdout = &stdout2
		if err2 := cmd2.Run(); err2 != nil {
			return "", fmt.Errorf("git diff failed: %w (stderr: %s)", err, stderr.String())
		}
		return stdout2.String(), nil
	}

	// If no uncommitted changes, check if the last commit was from auto-commit strategy
	if strings.TrimSpace(stdout.String()) == "" {
		cmd2 := exec.CommandContext(context.Background(), "git", "diff", "HEAD~1", "HEAD")
		cmd2.Dir = repoRoot
		var stdout2 bytes.Buffer
		cmd2.Stdout = &stdout2
		if err := cmd2.Run(); err == nil && strings.TrimSpace(stdout2.String()) != "" {
			return stdout2.String(), nil
		}
	}

	return stdout.String(), nil
}

